  PROMPT_VERSION: z.string().default("v1"),
  MOCK_LATENCY_MS: z.coerce.number().int().nonnegative().default(50),
  LOG_LEVEL: z.string().default("info"),
  ROLE: z.enum(["web", "worker", "migrate", "seed", "cli"]).default("cli"),
