29	export async function loadArticles(
30	  items: unknown[],
31	  batchKind: "live" | "backfill" = "backfill",
32	  pool?: pg.Pool,
33	  config?: AppConfig,
34	): Promise<LoadResult> {
35	  const cfg = config ?? loadConfig({ ...process.env, ROLE: process.env.ROLE ?? "seed" });
36	  const owned = !pool;
37	  const db = pool ?? createPool(cfg.db, "ingest");
38	
39	  const batchId = randomUUID();
40	  let admitted = 0;
41	  let quarantined = 0;
42	  let duplicate = 0;
43	  let errors = 0;
44	
45	  try {
46	    for (let position = 0; position < items.length; position++) {
47	      const item = items[position];
48	      try {
49	        const outcome = await ingestOne(db, item, batchId, batchKind, position, cfg.promptVersion);
50	        if (outcome === "admitted") admitted++;
51	        else if (outcome === "quarantined") quarantined++;
52	        else if (outcome === "error") {
53	          quarantined++;
54	          errors++;
55	        } else duplicate++;
56	      } catch (e) {
57	        if (isConnectionError(e)) throw e;
58	        log.error({ err: e, position }, "ingest item failed unexpectedly");
59	        const recorded = await recordItemError(db, item, batchId, batchKind, position, e);
60	        if (recorded) {
61	          quarantined++;
62	          errors++;
63	        } else {
64	          throw e;
65	        }
66	      }
67	    }
68	  } finally {
69	    if (owned) await db.end();
70	  }
71	
72	  return {
73	    received: items.length,
74	    admitted,
75	    quarantined,
76	    duplicate,
77	    errors,
78	    batchId,
79	  };
80	}
