82	function isConnectionError(e: unknown): boolean {
83	  if (!e || typeof e !== "object") return false;
84	  const err = e as { code?: string; message?: string };
85	  if (err.code === "ECONNREFUSED" || err.code === "ECONNRESET" || err.code === "57P01") return true;
86	  if (err.code === "57P03" || err.code === "08006" || err.code === "08003") return true;
87	  const msg = (err.message ?? "").toLowerCase();
88	  return (
89	    msg.includes("connection terminated") ||
90	    msg.includes("connection refused") ||
91	    msg.includes("cannot use a pool after calling end") ||
92	    msg.includes("client was closed")
93	  );
94	}
