96	/** Strip NULs and unpaired UTF-16 surrogates. */
97	export function repairText(input: string | null): string | null {
98	  if (input === null) return null;
99	  let out = "";
100	  for (let i = 0; i < input.length; i++) {
101	    const c = input.charCodeAt(i);
102	    if (c === 0) continue;
103	    if (c >= 0xd800 && c <= 0xdbff) {
104	      const next = input.charCodeAt(i + 1);
105	      if (next >= 0xdc00 && next <= 0xdfff) {
106	        out += input[i]! + input[i + 1]!;
107	        i++;
108	      }
109	      // else drop lone high surrogate
110	    } else if (c >= 0xdc00 && c <= 0xdfff) {
111	      // drop lone low surrogate
112	    } else {
113	      out += input[i]!;
114	    }
115	  }
116	  return out;
117	}
