119	async function quarantine(
120	  client: pg.PoolClient,
121	  opts: {
122	    batchId: string;
123	    batchKind: "live" | "backfill";
124	    position: number;
125	    payloadSha: Buffer;
126	    byteSize: number;
127	    reasonCodes: string[];
128	    fieldErrors?: unknown;
129	    payload: string;
130	  },
131	): Promise<void> {
132	  const ev = await client.query<{ id: string }>(
133	    `INSERT INTO ingest_events (batch_id, batch_kind, position, payload_sha256, byte_size, outcome, reason_codes)
134	     VALUES ($1::uuid, $2, $3, $4, $5, 'quarantined', $6)
135	     RETURNING id`,
136	    [
137	      opts.batchId,
138	      opts.batchKind,
139	      opts.position,
140	      opts.payloadSha,
141	      opts.byteSize,
142	      opts.reasonCodes,
143	    ],
144	  );
145	  await client.query(
146	    `INSERT INTO ingest_quarantine (event_id, reason_codes, field_errors, payload_text)
147	     VALUES ($1, $2, $3, $4)`,
148	    [
149	      ev.rows[0]!.id,
150	      opts.reasonCodes,
151	      opts.fieldErrors ?? null,
152	      opts.payload.slice(0, 1_048_576),
153	    ],
154	  );
155	}
