157	async function recordItemError(
158	  db: pg.Pool,
159	  item: unknown,
160	  batchId: string,
161	  batchKind: "live" | "backfill",
162	  position: number,
163	  err: unknown,
164	): Promise<boolean> {
165	  const payload = (() => {
166	    try {
167	      return JSON.stringify(item);
168	    } catch {
169	      return String(item);
170	    }
171	  })();
172	  const payloadSha = createHash("sha256").update(payload).digest();
173	  const byteSize = Buffer.byteLength(payload, "utf8");
174	  const client = await db.connect();
175	  try {
176	    await client.query("BEGIN");
177	    await quarantine(client, {
178	      batchId,
179	      batchKind,
180	      position,
181	      payloadSha,
182	      byteSize,
183	      reasonCodes: ["ingest_error"],
184	      fieldErrors: { message: err instanceof Error ? err.message.slice(0, 500) : String(err) },
185	      payload,
186	    });
187	    await client.query("COMMIT");
188	    return true;
189	  } catch (e) {
190	    await client.query("ROLLBACK").catch(() => undefined);
191	    if (isConnectionError(e)) throw e;
192	    return false;
193	  } finally {
194	    client.release();
195	  }
196	}
