3	export type Result<T> =
4	  | { ok: true; value: T; flags: string[] }
5	  | { ok: false; reasonCodes: string[]; fieldErrors?: Record<string, string> };
6	
7	const PLACEHOLDERS = new Set(["null", "n/a", "none", "undefined"]);
8	
9	function isPlaceholder(s: string): boolean {
10	  return PLACEHOLDERS.has(s.trim().toLowerCase());
11	}
12	
13	const rawArticleSchema = z.object({
14	  id: z.union([z.string(), z.number()]),
15	  source: z.unknown(),
16	  published_at: z.unknown(),
17	  language: z.unknown().optional(),
18	  headline: z.unknown().optional(),
19	  body: z.unknown().optional(),
20	});
21	
22	export type ValidatedArticle = {
23	  externalId: string;
24	  source: string;
25	  publishedAt: Date;
26	  language: string;
27	  headline: string | null;
28	  body: string | null;
29	  flags: string[];
30	  rawBytes: number;
31	};
32	
33	export function validateArticle(raw: unknown, now = new Date()): Result<ValidatedArticle> {
34	  const flags: string[] = [];
35	  const parsed = rawArticleSchema.safeParse(raw);
36	  if (!parsed.success) {
37	    return { ok: false, reasonCodes: ["payload_invalid"] };
38	  }
39	  const item = parsed.data;
40	  const jsonSize = Buffer.byteLength(JSON.stringify(item), "utf8");
41	  if (jsonSize > 1_048_576) {
42	    return { ok: false, reasonCodes: ["payload_too_large"] };
43	  }
44	
45	  let externalId: string;
46	  if (typeof item.id === "number" && Number.isFinite(item.id)) {
47	    externalId = String(item.id);
48	  } else if (typeof item.id === "string" && item.id.trim() && item.id.length <= 128) {
49	    externalId = item.id.trim();
50	  } else {
51	    return { ok: false, reasonCodes: ["id_invalid"] };
52	  }
53	
54	  if (typeof item.source !== "string" || !item.source.trim()) {
55	    return { ok: false, reasonCodes: ["source_missing"] };
56	  }
57	  const source = item.source.trim();
58	  if (source.length > 256 || isPlaceholder(source)) {
59	    return { ok: false, reasonCodes: ["source_placeholder"] };
60	  }
61	
62	  if (typeof item.published_at !== "string" || !item.published_at) {
63	    return { ok: false, reasonCodes: ["published_at_missing"] };
64	  }
65	  const pubStr = item.published_at;
66	  if (!/[zZ]|[+-]\d{2}:?\d{2}$/.test(pubStr)) {
67	    return { ok: false, reasonCodes: ["published_at_no_timezone"] };
68	  }
69	  const publishedAt = new Date(pubStr);
70	  if (Number.isNaN(publishedAt.getTime())) {
71	    return { ok: false, reasonCodes: ["published_at_invalid"] };
72	  }
73	  const min = new Date("1990-01-01T00:00:00Z");
74	  const max = new Date(now.getTime() + 24 * 3600_000);
75	  if (publishedAt < min) return { ok: false, reasonCodes: ["published_at_ancient"] };
76	  if (publishedAt > max) return { ok: false, reasonCodes: ["published_at_future"] };
77	  if (publishedAt > now) flags.push("published_at_skew");
78	
79	  let language = "und";
80	  if (typeof item.language === "string" && item.language.trim()) {
81	    const lang = item.language.trim();
82	    if (/^[A-Za-z]{2,8}(-[A-Za-z0-9]{1,8})*$/.test(lang) && lang.length <= 35) {
83	      language = lang;
84	    } else {
85	      flags.push("language_malformed");
86	    }
87	  } else {
88	    flags.push("language_missing");
89	  }
90	
91	  const headline = coerceText(item.headline, flags, "headline");
92	  const body = coerceText(item.body, flags, "body");
93	
94	  if (headline === null && body === null) {
95	    return { ok: false, reasonCodes: ["no_text"] };
96	  }
97	  if (headline && headline.length > 1000) flags.push("headline_oversized");
98	
99	  return {
100	    ok: true,
101	    value: {
102	      externalId,
103	      source,
104	      publishedAt,
105	      language,
106	      headline,
107	      body,
108	      flags,
109	      rawBytes: jsonSize,
110	    },
111	    flags,
112	  };
113	}
114	
115	function coerceText(
116	  value: unknown,
117	  flags: string[],
118	  field: "headline" | "body",
119	): string | null {
120	  if (value === null || value === undefined) {
121	    flags.push(`${field}_missing`);
122	    return null;
123	  }
124	  if (typeof value !== "string") {
125	    flags.push(`${field}_missing`);
126	    return null;
127	  }
128	  const t = value.trim();
129	  if (!t || isPlaceholder(t)) {
130	    flags.push(`${field}_placeholder`);
131	    return null;
132	  }
133	  return value;
134	}
