x-app: &app
  image: media-signal-app:local
  build: { context: ., target: runner }
  init: true
  read_only: true
  cap_drop: [ALL]
  security_opt: ["no-new-privileges:true"]
  logging: *logging
  env_file:
    - path: .env
      required: false

services:
  secrets-init:
    image: alpine:3.20.3
    volumes:
      - secrets:/secrets
      - ./ops/init-secrets.sh:/init.sh:ro
    command: ["sh", "/init.sh"]
    restart: "no"
    mem_limit: 64m

  db:
    image: postgres:16.6-bookworm
    depends_on:
      secrets-init:
        condition: service_completed_successfully
    environment:
      POSTGRES_USER: mss_admin
      POSTGRES_DB: ${DB_NAME:-mss}
      POSTGRES_PASSWORD_FILE: /run/secrets/postgres_password
      POSTGRES_INITDB_ARGS: "--locale=C.UTF-8 --encoding=UTF8"
    command: ["postgres", "-c", "config_file=/etc/postgresql/postgresql.conf"]
    volumes:
      - pgdata:/var/lib/postgresql/data
      - type: volume
        source: secrets
        target: /run/secrets
        read_only: true
        volume:
          subpath: db
      - ./db/postgres/${DB_TUNING:-small}.conf:/etc/postgresql/postgresql.conf:ro
    shm_size: 256mb
    mem_limit: 1g
    healthcheck:
      test: ["CMD-SHELL", "pg_isready -h 127.0.0.1 -U mss_admin -d $${POSTGRES_DB}"]
      interval: 5s
      timeout: 3s
      retries: 20
      start_period: 10s
    restart: unless-stopped
    networks: [data]
