    if (!art.rows[0]) notFound();
    const a = art.rows[0];
    const derived = await pool.query(
      `SELECT * FROM derived_values WHERE article_id = $1 AND is_current ORDER BY field, rank`,
      [id],
    );
    const jobs = await pool.query(
      `SELECT * FROM enrichment_jobs WHERE article_id = $1 ORDER BY part`,
      [id],
    );
    const transforms = await pool.query(
      `SELECT * FROM ingest_transformations WHERE article_id = $1 ORDER BY id`,
      [id],
    );
    const enrichments = await pool.query(
      `SELECT * FROM enrichments WHERE article_id = $1 ORDER BY created_at`,
      [id],
    );
    const dups = await pool.query(
      `SELECT id, external_id, source FROM articles WHERE content_hash = $1 AND id <> $2`,
      [a.content_hash, id],
    );

